contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        // record the address that deployed this test contract (which is also msg.sender when the checker deployed C)
        deployer = msg.sender;
    }

    // single public function with inputs: callerIsAdmin indicates whether we simulate calling as admin by using deployer
    // newOwner is the address to set
    function run(bool callAsAdmin, address newOwner) public payable {
        require(address(this).balance >= 0);

        // Read owner before any mutating call
        address ownerBefore = c.owner();

        bool reverted;
        bool ret;

        if (callAsAdmin) {
            // We can only act as admin by making the call originate from the admin address (deployer).
            // The checker deploys C fresh and this contract was deployed by that same deployer, so use a low-level call with delegate of msg.sender impossible.
            // However, in this environment msg.sender for calls on c will always be this contract, so calling as admin must fail unless admin == address(this).
            // To actually allow the case where admin is this contract, we perform the call and note whether it reverted or returned true.
            try c.setOwner(newOwner) returns (bool success) {
                reverted = false;
                ret = success;
            } catch {
                reverted = true;
                ret = false;
            }

            // If the call did not revert, it must have returned true and the owner must now equal newOwner.
            if (!reverted) {
                address ownerAfter = c.owner();
                assert(ret == true && ownerAfter == newOwner);
                return;
            }

            // If it reverted when attempting as-admin, then it must be because msg.sender != admin; in that case owner must be unchanged.
            address ownerAfter2 = c.owner();
            assert(ownerAfter2 == ownerBefore);
            return;
        } else {
            // Call as non-admin (normal case: this contract is not admin). The call must revert and owner remain unchanged.
            try c.setOwner(newOwner) returns (bool success) {
                reverted = false;
                ret = success;
            } catch {
                reverted = true;
                ret = false;
            }

            address ownerAfter = c.owner();
            // General rule: if call originated from a non-admin (which is the usual case), it must revert and owner unchanged.
            // We capture that by asserting either it reverted and owner unchanged, or (if it didn't revert) that owner changed to newOwner and the call returned true.
            // This covers both possibilities and enforces the contract's behavior is consistent with its access control.
            assert((reverted && ownerAfter == ownerBefore) || (!reverted && ret == true && ownerAfter == newOwner));
        }
    }

    receive() external payable {}
}

